access-gate.translation:
Instrução: Adicionar portão de código de acesso ao shortcode de admin. Usuários sem manage_options precisam digitar o código (salvo em wp_options) para acessar o sistema. Quatro arquivos: plugin-packs-chama-coins.php, includes/class-activator.php, admin/class-admin-page.php, assets/style.css.

=== 1. plugin-packs-chama-coins.php — iniciar sessão PHP no hook init ===

Após as linhas de definição das constantes (após o último define()), antes da linha que inclui os arquivos PHP (require/include), adicionar:

    add_action( 'init', function () {
        if ( ! session_id() && ! headers_sent() ) {
            session_start();
        }
    }, 1 );

=== 2. includes/class-activator.php — registrar option padrão no activate() ===

No método activate(), após self::maybe_migrate(), adicionar:
    add_option( 'cc_packs_access_code', '24654785Gm@' );

=== 3. admin/class-admin-page.php — gate de acesso na render() ===

Localizar o método render() completo:
    public function render( array $atts ): string {
        if ( ! $this->check_access() ) return '';
        $mode       = ...
        ...
        return $nav . $this->render_crud_mode();
    }

Substituir o método render() inteiro por:

    public function render( array $atts ): string {
        // Admins WordPress: acesso direto
        if ( ! current_user_can( 'manage_options' ) ) {
            // Verifica se sessão já validou o código
            if ( empty( $_SESSION['cc_packs_gate_ok'] ) ) {
                // Processa envio do formulário de código
                if ( isset( $_POST['cc_access_code'] ) ) {
                    if ( ! wp_verify_nonce( $_POST['_wpnonce'] ?? '', 'cc_gate_submit' ) ) {
                        return $this->render_access_gate( true );
                    }
                    $submitted = sanitize_text_field( $_POST['cc_access_code'] );
                    $stored    = get_option( 'cc_packs_access_code', '24654785Gm@' );
                    if ( hash_equals( $stored, $submitted ) ) {
                        $_SESSION['cc_packs_gate_ok'] = true;
                    } else {
                        return $this->render_access_gate( true );
                    }
                } else {
                    return $this->render_access_gate( false );
                }
            }
        }

        $mode       = isset( $_GET['cc_mode'] ) && $_GET['cc_mode'] === 'orders' ? 'orders' : 'crud';
        $base_url   = get_permalink();
        $crud_url   = remove_query_arg( 'cc_mode', $base_url );
        $orders_url = add_query_arg( 'cc_mode', 'orders', $base_url );
        $nav = '<nav class="cc-admin-nav">'
            . '<a href="' . esc_url( $crud_url )   . '" class="' . ( $mode === 'crud'   ? 'is-active' : '' ) . '">📦 Packs</a>'
            . '<a href="' . esc_url( $orders_url ) . '" class="' . ( $mode === 'orders' ? 'is-active' : '' ) . '">📋 Pedidos</a>'
            . '</nav>';
        if ( $mode === 'orders' ) return $nav . $this->render_orders_mode();
        return $nav . $this->render_crud_mode();
    }

=== 4. admin/class-admin-page.php — adicionar método render_access_gate() ===

Após o método check_access() (que termina com return current_user_can('manage_options');  }), inserir o novo método:

    private function render_access_gate( bool $error = false ): string {
        ob_start();
        ?>
        <div class="cc-access-gate">
            <div class="cc-access-gate-card">
                <span class="cc-access-gate-icon">🔒</span>
                <h2 class="cc-access-gate-title">Área Restrita</h2>
                <p class="cc-access-gate-subtitle">Digite o código de acesso para continuar</p>
                <form class="cc-access-gate-form" method="post">
                    <?php wp_nonce_field( 'cc_gate_submit' ); ?>
                    <input
                        type="password"
                        name="cc_access_code"
                        class="cc-access-gate-input"
                        placeholder="Código de acesso"
                        autocomplete="off"
                        autofocus
                        required
                    >
                    <?php if ( $error ) : ?>
                        <p class="cc-access-gate-error">❌ Código inválido. Tente novamente.</p>
                    <?php endif; ?>
                    <button type="submit" class="cc-access-gate-btn">Entrar</button>
                </form>
            </div>
        </div>
        <?php
        return ob_get_clean();
    }

=== 5. assets/style.css — estilos do portão de acesso ===

Ao final do arquivo, adicionar:

/* ==========================================================
   Portão de Acesso — Código de Acesso
   ========================================================== */

.cc-access-gate {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 60vh;
    padding: 40px 16px;
}

.cc-access-gate-card {
    background: var(--cc-surface);
    border: 1px solid var(--cc-border-mid);
    border-radius: var(--cc-r-lg, 16px);
    padding: 48px 40px 40px;
    max-width: 400px;
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0;
    box-shadow: 0 8px 40px rgba(0,0,0,.5);
    text-align: center;
}

.cc-access-gate-icon {
    font-size: 42px;
    line-height: 1;
    margin-bottom: 20px;
    display: block;
    filter: drop-shadow(0 0 16px rgba(255,102,0,.4));
}

.cc-access-gate-title {
    font-size: 22px;
    font-weight: 800;
    color: var(--cc-text);
    margin: 0 0 8px;
    letter-spacing: -.3px;
}

.cc-access-gate-subtitle {
    font-size: 14px;
    color: var(--cc-text-muted);
    margin: 0 0 28px;
    line-height: 1.5;
}

.cc-access-gate-form {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.cc-access-gate-input {
    width: 100%;
    background: var(--cc-bg);
    border: 1px solid var(--cc-border-mid);
    border-radius: var(--cc-r-sm);
    color: var(--cc-text);
    padding: 14px 16px;
    font-size: 15px;
    outline: none;
    text-align: center;
    letter-spacing: 3px;
    transition: border-color var(--cc-t), box-shadow var(--cc-t);
    box-sizing: border-box;
}

.cc-access-gate-input::placeholder {
    letter-spacing: normal;
    color: var(--cc-text-muted);
    font-size: 14px;
}

.cc-access-gate-input:focus {
    border-color: var(--cc-accent);
    box-shadow: 0 0 0 2px var(--cc-accent-dim);
}

.cc-access-gate-error {
    font-size: 13px;
    color: #ff4d4d;
    background: rgba(255,77,77,.08);
    border: 1px solid rgba(255,77,77,.2);
    border-radius: var(--cc-r-xs);
    padding: 9px 14px;
    margin: 0;
}

.cc-access-gate-btn {
    background: var(--cc-accent);
    color: #000;
    border: none;
    border-radius: var(--cc-r-sm);
    padding: 14px 20px;
    font-size: 15px;
    font-weight: 800;
    cursor: pointer;
    transition: opacity var(--cc-t), transform var(--cc-t);
    letter-spacing: -.1px;
    margin-top: 4px;
}

.cc-access-gate-btn:hover {
    opacity: .88;
    transform: translateY(-1px);
}

.cc-access-gate-btn:active {
    transform: translateY(0);
    opacity: 1;
}

Verificação: (1) plugin-packs-chama-coins.php tem add_action('init') com session_start() protegido por headers_sent(). (2) activate() chama add_option('cc_packs_access_code', '24654785Gm@'). (3) render() verifica current_user_can('manage_options') e, para não-admins, checa $_SESSION['cc_packs_gate_ok'] — processa POST com wp_verify_nonce e hash_equals, retorna render_access_gate() se não verificado. (4) Método render_access_gate(bool $error) existe com form de POST, wp_nonce_field e campo de password. (5) CSS adicionado ao final de assets/style.css cobrindo .cc-access-gate, .cc-access-gate-card, .cc-access-gate-input, .cc-access-gate-error e .cc-access-gate-btn.
